import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    n = int(input_data[0])
    k = int(input_data[1])
    a = []
    for i in range(n):
        a.append(int(input_data[2 + i]))

    if k == 1:
        print(0)
        return

    a.sort()
    present = set(a)

    count = 0
    for x in a:
        if x in present:
            count += 1
            if x * k in present:
                present.remove(x * k)

    print(n - len(present))

if __name__ == "__main__":
    solve()
